// Classifiers, trees, and how to judge them.
import { mean, sum, entropy as H } from './stats.js';

export const sigmoid = (z) => 1 / (1 + Math.exp(-z));
export function confusion(truth, pred) { let tp = 0, fp = 0, tn = 0, fn = 0; for (let i = 0; i < truth.length; i++) { if (truth[i] && pred[i]) tp++; else if (!truth[i] && pred[i]) fp++; else if (!truth[i] && !pred[i]) tn++; else fn++; } return metrics({ tp, fp, tn, fn }); }
export function metrics({ tp, fp, tn, fn }) { const n = tp + fp + tn + fn, precision = tp + fp ? tp / (tp + fp) : 0, recall = tp + fn ? tp / (tp + fn) : 0; return { tp, fp, tn, fn, n, accuracy: n ? (tp + tn) / n : 0, precision, recall, specificity: tn + fp ? tn / (tn + fp) : 0, f1: precision + recall ? (2 * precision * recall) / (precision + recall) : 0 }; }
export function roc(truth, score) { const idx = score.map((s, i) => [s, truth[i]]).sort((a, b) => b[0] - a[0]), P = truth.filter(Boolean).length, N = truth.length - P; let tp = 0, fp = 0; const pts = [[0, 0]]; for (const [, t] of idx) { if (t) tp++; else fp++; pts.push([N ? fp / N : 0, P ? tp / P : 0]); } let auc = 0; for (let i = 1; i < pts.length; i++) auc += (pts[i][0] - pts[i - 1][0]) * (pts[i][1] + pts[i - 1][1]) / 2; return { pts, auc }; }
export function kappa(m) { const po = m.accuracy, pe = ((m.tp + m.fp) * (m.tp + m.fn) + (m.fn + m.tn) * (m.fp + m.tn)) / (m.n * m.n); return pe === 1 ? 0 : (po - pe) / (1 - pe); }
export function ndcg(rel, k) { const dcg = (r) => r.slice(0, k).reduce((s, v, i) => s + v / Math.log2(i + 2), 0), ideal = dcg(rel.slice().sort((a, b) => b - a)); return ideal ? dcg(rel) / ideal : 0; }

// logistic regression by gradient descent; X rows without intercept
export function logistic(X, y, { lr = 0.3, iters = 400, l2 = 0 } = {}) { const p = X[0].length, w = new Array(p + 1).fill(0), n = X.length; for (let it = 0; it < iters; it++) { const g = new Array(p + 1).fill(0); for (let i = 0; i < n; i++) { const z = w[0] + X[i].reduce((s, v, j) => s + v * w[j + 1], 0), e = sigmoid(z) - y[i]; g[0] += e; for (let j = 0; j < p; j++) g[j + 1] += e * X[i][j]; } for (let j = 0; j <= p; j++) w[j] -= lr * (g[j] / n + (j ? l2 * w[j] : 0)); } return { w, prob: (r) => sigmoid(w[0] + r.reduce((s, v, j) => s + v * w[j + 1], 0)) }; }
export function logLoss(y, p) { let s = 0; for (let i = 0; i < y.length; i++) { const q = Math.min(1 - 1e-12, Math.max(1e-12, p[i])); s -= y[i] * Math.log(q) + (1 - y[i]) * Math.log(1 - q); } return s / y.length; }
// Naive Bayes over words, with Laplace smoothing
export function naiveBayes(docs, labels, alpha = 1) { const classes = [...new Set(labels)], vocab = new Set(docs.flat()), prior = {}, counts = {}, totals = {}; for (const c of classes) { prior[c] = labels.filter((l) => l === c).length / labels.length; counts[c] = new Map(); totals[c] = 0; } docs.forEach((d, i) => { for (const w of d) { counts[labels[i]].set(w, (counts[labels[i]].get(w) || 0) + 1); totals[labels[i]]++; } }); const like = (w, c) => ((counts[c].get(w) || 0) + alpha) / (totals[c] + alpha * vocab.size); return { classes, prior, like, score(d) { const s = {}; for (const c of classes) s[c] = Math.log(prior[c]) + d.reduce((t, w) => t + Math.log(like(w, c)), 0); const m = Math.max(...Object.values(s)), z = Object.values(s).reduce((t, v) => t + Math.exp(v - m), 0), post = {}; for (const c of classes) post[c] = Math.exp(s[c] - m) / z; return post; } }; }
// perceptron
export function perceptronStep(w, x, y, lr = 1) { const pred = w[0] + w[1] * x[0] + w[2] * x[1] >= 0 ? 1 : 0; if (pred !== y) { const d = (y - pred) * lr; w[0] += d; w[1] += d * x[0]; w[2] += d * x[1]; return true; } return false; }
// linear SVM by sub-gradient descent on the hinge loss; y in {-1, +1}
export function svm(X, y, { C = 1, lr = 0.01, iters = 800 } = {}) { let w = [0, 0], b = 0; for (let it = 0; it < iters; it++) { let gw = [w[0], w[1]], gb = 0; for (let i = 0; i < X.length; i++) { const m = y[i] * (w[0] * X[i][0] + w[1] * X[i][1] + b); if (m < 1) { gw[0] -= C * y[i] * X[i][0]; gw[1] -= C * y[i] * X[i][1]; gb -= C * y[i]; } } w = [w[0] - lr * gw[0], w[1] - lr * gw[1]]; b -= lr * gb; } return { w, b, margin: 2 / (Math.hypot(w[0], w[1]) || 1e-9) }; }
export function marginOf(w, b, X, y) { const n = Math.hypot(w[0], w[1]) || 1e-9; let m = Infinity; for (let i = 0; i < X.length; i++) m = Math.min(m, (y[i] * (w[0] * X[i][0] + w[1] * X[i][1] + b)) / n); return m; }

// ---- decision trees (CART) ----
export const giniImp = (counts) => { const t = sum(counts); return t ? 1 - sum(counts.map((c) => (c / t) ** 2)) : 0; };
export const entropyImp = (counts) => H(counts);
function countsOf(y, idx, K) { const c = new Array(K).fill(0); for (const i of idx) c[y[i]]++; return c; }
export function bestSplit(X, y, idx, K, imp = giniImp) { const parent = imp(countsOf(y, idx, K)); let best = null; for (let f = 0; f < X[0].length; f++) { const vals = [...new Set(idx.map((i) => X[i][f]))].sort((a, b) => a - b); for (let v = 0; v < vals.length - 1; v++) { const th = (vals[v] + vals[v + 1]) / 2, L = idx.filter((i) => X[i][f] <= th), R = idx.filter((i) => X[i][f] > th), g = parent - (L.length * imp(countsOf(y, L, K)) + R.length * imp(countsOf(y, R, K))) / idx.length; if (!best || g > best.gain) best = { f, th, gain: g, L, R }; } } return best; }
export function growTree(X, y, { maxDepth = 4, minLeaf = 2, K = 2, imp = giniImp, features = null, rng = null } = {}) { const build = (idx, depth) => { const counts = countsOf(y, idx, K), node = { counts, n: idx.length, label: counts.indexOf(Math.max(...counts)), impurity: imp(counts) }; if (depth >= maxDepth || node.impurity === 0 || idx.length < minLeaf * 2) return node; let XX = X; if (features && rng) { const keep = rng.sample(X[0].map((_, j) => j), features); XX = X.map((r) => r.map((v, j) => (keep.includes(j) ? v : 0))); } const s = bestSplit(XX, y, idx, K, imp); if (!s || s.gain <= 1e-9 || s.L.length < minLeaf || s.R.length < minLeaf) return node; node.f = s.f; node.th = s.th; node.gain = s.gain; node.left = build(s.L, depth + 1); node.right = build(s.R, depth + 1); return node; }; return build(X.map((_, i) => i), 0); }
export function predictTree(node, x) { while (node.left) node = x[node.f] <= node.th ? node.left : node.right; return node.label; }
export function leaves(node) { return node.left ? leaves(node.left) + leaves(node.right) : 1; }
export function prune(node, minGain) { if (!node.left) return node; prune(node.left, minGain); prune(node.right, minGain); if (!node.left.left && !node.right.left && node.gain < minGain) { delete node.left; delete node.right; delete node.f; delete node.th; } return node; }
export function forest(X, y, rng, { trees = 15, maxDepth = 4, K = 2 } = {}) { const fs = []; for (let t = 0; t < trees; t++) { const idx = X.map(() => rng.int(0, X.length - 1)), Xb = idx.map((i) => X[i]), yb = idx.map((i) => y[i]); fs.push(growTree(Xb, yb, { maxDepth, K, features: Math.max(1, Math.round(Math.sqrt(X[0].length))), rng })); } return { trees: fs, predict(x) { const v = new Array(K).fill(0); for (const t of fs) v[predictTree(t, x)]++; return v.indexOf(Math.max(...v)); }, votes(x) { const v = new Array(K).fill(0); for (const t of fs) v[predictTree(t, x)]++; return v; } }; }
// AdaBoost with one-split stumps; y in {-1, +1}
export function adaboost(X, y, rounds = 10) { const n = X.length; let w = new Array(n).fill(1 / n); const stumps = []; for (let r = 0; r < rounds; r++) { let best = null; for (let f = 0; f < X[0].length; f++) { const vals = [...new Set(X.map((x) => x[f]))].sort((a, b) => a - b); for (let v = 0; v < vals.length - 1; v++) for (const s of [1, -1]) { const th = (vals[v] + vals[v + 1]) / 2; let err = 0; for (let i = 0; i < n; i++) if ((X[i][f] <= th ? s : -s) !== y[i]) err += w[i]; if (!best || err < best.err) best = { f, th, s, err }; } } if (!best) break; const e = Math.min(Math.max(best.err, 1e-9), 1 - 1e-9), a = 0.5 * Math.log((1 - e) / e); stumps.push({ ...best, a }); w = w.map((wi, i) => wi * Math.exp(-a * y[i] * (X[i][best.f] <= best.th ? best.s : -best.s))); const z = sum(w); w = w.map((v) => v / z); if (best.err < 1e-9) break; } const score = (x) => sum(stumps.map((s) => s.a * (x[s.f] <= s.th ? s.s : -s.s))); return { stumps, score, predict: (x) => (score(x) >= 0 ? 1 : -1), weights: w }; }
// isolation forest
function iTree(X, idx, depth, limit, rng) { if (depth >= limit || idx.length <= 1) return { size: idx.length }; const f = rng.int(0, X[0].length - 1), vals = idx.map((i) => X[i][f]), lo = Math.min(...vals), hi = Math.max(...vals); if (lo === hi) return { size: idx.length }; const th = rng.range(lo, hi); return { f, th, left: iTree(X, idx.filter((i) => X[i][f] < th), depth + 1, limit, rng), right: iTree(X, idx.filter((i) => X[i][f] >= th), depth + 1, limit, rng) }; }
const cFactor = (n) => (n > 2 ? 2 * (Math.log(n - 1) + 0.5772156649) - (2 * (n - 1)) / n : n === 2 ? 1 : 0);
export function pathLength(tree, x, depth = 0) { if (!tree.left) return depth + cFactor(tree.size); return pathLength(x[tree.f] < tree.th ? tree.left : tree.right, x, depth + 1); }
export function isolationForest(X, rng, { trees = 60, sample = 64 } = {}) { const ts = [], n = Math.min(sample, X.length), limit = Math.ceil(Math.log2(n)); for (let t = 0; t < trees; t++) ts.push(iTree(X, rng.sample(X.map((_, i) => i), n), 0, limit, rng)); const c = cFactor(n); return { trees: ts, score: (x) => Math.pow(2, -mean(ts.map((t) => pathLength(t, x))) / c), depth: (x) => mean(ts.map((t) => pathLength(t, x))) }; }
export function lof(points, k, dist) { const n = points.length, nb = points.map((p, i) => points.map((q, j) => [dist(p, q), j]).filter((x) => x[1] !== i).sort((a, b) => a[0] - b[0]).slice(0, k)), kd = nb.map((l) => l[l.length - 1][0]), lrd = nb.map((l, i) => 1 / (mean(l.map(([d, j]) => Math.max(kd[j], d))) || 1e-9)); return nb.map((l, i) => mean(l.map(([, j]) => lrd[j])) / lrd[i]); }
// lasso for one feature set by coordinate descent (features should be standardised)
export function lasso(X, y, lam, iters = 200) { const n = X.length, p = X[0].length, w = new Array(p).fill(0), my = mean(y), r = y.map((v) => v - my), norm = X[0].map((_, j) => sum(X.map((row) => row[j] * row[j])) / n); for (let it = 0; it < iters; it++) for (let j = 0; j < p; j++) { let rho = 0; for (let i = 0; i < n; i++) rho += X[i][j] * (r[i] + w[j] * X[i][j]); rho /= n; const nw = norm[j] ? Math.sign(rho) * Math.max(0, Math.abs(rho) - lam) / norm[j] : 0; if (nw !== w[j]) { for (let i = 0; i < n; i++) r[i] += (w[j] - nw) * X[i][j]; w[j] = nw; } } return { w, b: my, nonzero: w.filter((v) => Math.abs(v) > 1e-9).length }; }
export function kfold(n, k, rng) { const idx = rng ? rng.shuffle(Array.from({ length: n }, (_, i) => i)) : Array.from({ length: n }, (_, i) => i); return Array.from({ length: k }, (_, f) => ({ test: idx.filter((_, i) => i % k === f), train: idx.filter((_, i) => i % k !== f) })); }
